import{_ as a,f as n,o as l,aq as e}from"./chunks/framework.D7yxI9Ht.js";const b=JSON.parse('{"title":"复数","description":"","frontmatter":{},"headers":[],"relativePath":"zh_CN/digging-deeper/pluralization.md","filePath":"zh_CN/digging-deeper/pluralization.md","lastUpdated":1789751181000}'),p={name:"zh_CN/digging-deeper/pluralization.md"};function o(r,s,t,c,i,u){return l(),n("div",null,s[0]||(s[0]=[e(`<h1 id="复数" tabindex="-1">复数 <a class="header-anchor" href="#复数" aria-label="Permalink to “复数”">​</a></h1><h2 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h2><p>字符串对于任何 Web 应用程序都很重要。 Goravel 提供了简单的工具在单数和复数形式之间转换单词。 它默认支持<strong>英语</strong>，但你可以轻松添加其他语言或自定义规则。</p><h2 id="基本用法" tabindex="-1">基本用法 <a class="header-anchor" href="#基本用法" aria-label="Permalink to “基本用法”">​</a></h2><p>你可以使用 <code>pluralizer</code> 包中的 <code>Plural</code> 和 <code>Singular</code> 方法。 这些方法会自动处理大多数英语单词。</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">github.com/goravel/framework/support/pluralizer</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// 复数化单词</span></span>
<span class="line"><span style="color:#101820;">pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Plural</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;goose&quot;</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> // &quot;geese&quot;</span></span>
<span class="line"><span style="color:#101820;">pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Plural</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;car&quot;</span><span style="color:#68747D;">)</span><span style="color:#68747D;">   // &quot;cars&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// 单数化单词</span></span>
<span class="line"><span style="color:#101820;">pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Singular</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;geese&quot;</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> // &quot;goose&quot;</span></span>
<span class="line"><span style="color:#101820;">pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Singular</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;cars&quot;</span><span style="color:#68747D;">)</span><span style="color:#68747D;">  // &quot;car&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="自定义规则" tabindex="-1">自定义规则 <a class="header-anchor" href="#自定义规则" aria-label="Permalink to “自定义规则”">​</a></h2><p>有时默认规则不足以处理特定单词。 Goravel 允许你添加自己的规则来处理这些情况。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>添加规则会全局改变复数化的工作方式。 你应该在应用程序启动时执行此操作，例如在服务提供者的 <code>Boot</code> 方法中。</p></div><h3 id="不规则单词" tabindex="-1">不规则单词 <a class="header-anchor" href="#不规则单词" aria-label="Permalink to “不规则单词”">​</a></h3><p>如果一个单词有独特的复数形式，你可以将其注册为“不规则”单词。 这会处理单数复数两个方向的变化。</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#68747D;">	&quot;</span><span style="color:#101820;">github.com/goravel/framework/support/pluralizer</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">    &quot;</span><span style="color:#101820;">github.com/goravel/framework/support/pluralizer/rules</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// 注册“mouse”变为“mice”</span></span>
<span class="line"><span style="color:#101820;">pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">RegisterIrregular</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;english&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> rules</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">NewSubstitution</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;mouse&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;mice&quot;</span><span style="color:#68747D;">))</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="无变化单词" tabindex="-1">无变化单词 <a class="header-anchor" href="#无变化单词" aria-label="Permalink to “无变化单词”">​</a></h3><p>有些单词如 “fish” 或 “media” 不会改变形式或始终是复数。 你可以将这些标记为“无变化”，以便复数化器跳过它们。</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#68747D;">// “sheep”在单数和复数中都保持“sheep”</span></span>
<span class="line"><span style="color:#101820;">pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">RegisterUninflected</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;english&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;sheep&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// “media”始终被视为复数</span></span>
<span class="line"><span style="color:#101820;">pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">RegisterPluralUninflected</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;english&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;media&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// “data”始终被视为单数</span></span>
<span class="line"><span style="color:#101820;">pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">RegisterSingularUninflected</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;english&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> &quot;data&quot;</span><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="语言支持" tabindex="-1">语言支持 <a class="header-anchor" href="#语言支持" aria-label="Permalink to “语言支持”">​</a></h2><p>Goravel 默认使用 “english”，但你可以根据需要切换语言或添加新语言。</p><h3 id="切换语言" tabindex="-1">切换语言 <a class="header-anchor" href="#切换语言" aria-label="Permalink to “切换语言”">​</a></h3><p>如果你注册了其他语言，可以使用 <code>UseLanguage</code> 切换语言。</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">if err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">UseLanguage</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;spanish&quot;</span><span style="color:#68747D;">);</span><span style="color:#101820;"> err </span><span style="color:#68747D;">!=</span><span style="color:#101820;"> nil </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#0077B3;">    panic</span><span style="color:#68747D;">(</span><span style="color:#101820;">err</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#68747D;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">// 获取当前语言名称</span></span>
<span class="line"><span style="color:#101820;">name </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">GetLanguage</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Name</span><span style="color:#68747D;">()</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="添加新语言" tabindex="-1">添加新语言 <a class="header-anchor" href="#添加新语言" aria-label="Permalink to “添加新语言”">​</a></h3><p>要添加一种语言，您需要实现 <code>Language</code> 接口。 这定义了该语言中单词的变化方式。</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">github.com/goravel/framework/contracts/support/pluralizer</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">type Language interface </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#0077B3;">    Name</span><span style="color:#68747D;">()</span><span style="color:#101820;"> string</span></span>
<span class="line"><span style="color:#0077B3;">    SingularRuleset</span><span style="color:#68747D;">()</span><span style="color:#101820;"> pluralizer</span><span style="color:#68747D;">.</span><span style="color:#101820;">Ruleset</span></span>
<span class="line"><span style="color:#0077B3;">    PluralRuleset</span><span style="color:#68747D;">()</span><span style="color:#101820;"> pluralizer</span><span style="color:#68747D;">.</span><span style="color:#101820;">Ruleset</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>实现你的语言结构体后，注册它并将其设置为默认语言。</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">github.com/goravel/framework/support/pluralizer</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">func </span><span style="color:#0077B3;">init</span><span style="color:#68747D;">()</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#68747D;">    // 注册新语言</span></span>
<span class="line"><span style="color:#101820;">    if err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">RegisterLanguage</span><span style="color:#68747D;">(&amp;</span><span style="color:#101820;">MyCustomLanguage</span><span style="color:#68747D;">{});</span><span style="color:#101820;"> err </span><span style="color:#68747D;">!=</span><span style="color:#101820;"> nil </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#0077B3;">       panic</span><span style="color:#68747D;">(</span><span style="color:#101820;">err</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#68747D;">    }</span></span>
<span class="line"><span style="color:#101820;">    </span></span>
<span class="line"><span style="color:#68747D;">    // 将其设置为默认语言</span></span>
<span class="line"><span style="color:#101820;">    _ </span><span style="color:#68747D;">=</span><span style="color:#101820;"> pluralizer</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">UseLanguage</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;my_custom_language&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h2 id="支持的语言" tabindex="-1">支持的语言 <a class="header-anchor" href="#支持的语言" aria-label="Permalink to “支持的语言”">​</a></h2><p>目前，复数化器开箱即用支持以下语言：</p><table tabindex="0"><thead><tr><th style="text-align:left;">语言</th><th style="text-align:left;">代码</th><th style="text-align:left;">来源</th></tr></thead><tbody><tr><td style="text-align:left;">英语</td><td style="text-align:left;"><code>english</code></td><td style="text-align:left;"><a href="https://github.com/goravel/framework/tree/master/support/pluralizer/english" target="_blank" rel="noreferrer">查看源代码</a></td></tr></tbody></table><p><em>未来版本将添加更多语言。 欢迎你通过 Pull Request 贡献新语言。</em></p>`,29)]))}const d=a(p,[["render",o]]);export{b as __pageData,d as default};
